# protects: real-work intake: a task in the real-work manifest at the repo's HEAD; nothing runs on an unconfirmed list
# run-after: tests/new-real-task.ps1
# test-new-real-task.ps1 - regression guard for tests/new-real-task.ps1 (Step 2, 2026-11-02).
#
# Why this exists: a real task from the owner must land in the REAL-WORK manifest (the benchmark's manifest.json is
# regenerated by build_manifest.py and would lose it), start from the repository's HEAD, carry no hidden tests
# (grading "checklist", its checklist the confirmed DONE.md), and never reach the model before the owner confirmed
# its done list. The planner and model steps need Docker and a server, so this guard covers what can be checked
# anywhere: `add`, its refusals, and `run`'s refusal of an unconfirmed list.
$ErrorActionPreference = "Stop"
$script = Join-Path $PSScriptRoot "new-real-task.ps1"
$doneTool = Join-Path (Split-Path -Parent $PSScriptRoot) "desktop/scripts/planner_done.py"
$script:fail = 0
function Check([string]$name, $actual, $expected) {
    if ("$actual" -eq "$expected") { Write-Host "PASS $name" }
    else { Write-Host "FAIL $name (got '$actual', expected '$expected')"; $script:fail++ }
}
function Run([string[]]$a) {
    $prev = $ErrorActionPreference; $ErrorActionPreference = "Continue"
    try { $o = & pwsh -NoProfile -File $script @a 2>&1 | Out-String; [pscustomobject]@{ Exit = $LASTEXITCODE; Out = $o } } finally { $ErrorActionPreference = $prev }
}
$python = $null
foreach ($cand in "python3", "python") { foreach ($c in @(Get-Command $cand -All -ErrorAction SilentlyContinue)) { $o = & $c.Source -c "print(40 + 2)" 2>$null | Out-String; if ($LASTEXITCODE -eq 0 -and $o.Trim() -eq "42") { $python = $c; break } }; if ($python) { break } }

$tmp = Join-Path ([IO.Path]::GetTempPath()) ("real-task-" + [guid]::NewGuid().ToString("N").Substring(0, 12))
$utf8 = New-Object System.Text.UTF8Encoding($false)
try {
    $repo = Join-Path $tmp "LFCbot"; $priv = Join-Path $tmp "HomeLab-private"
    New-Item -ItemType Directory -Force $repo, (Join-Path $priv "tasks") | Out-Null
    & git init -q $repo; & git -C $repo config user.email g@x; & git -C $repo config user.name g
    [IO.File]::WriteAllText((Join-Path $repo "a.txt"), "a`n", $utf8); & git -C $repo add -A; & git -C $repo commit -q -m base
    $head = (& git -C $repo rev-parse HEAD).Trim()
    $repoNorm = ((Resolve-Path $repo).Path -replace '\\', '/')
    $bench = @{ tasks = @(@{ id = "real-01"; repo = $repoNorm; testDir = "."; testCmd = @("npx", "vitest", "run"); installFlags = @("--ignore-scripts"); packageManager = "npm" }) } | ConvertTo-Json -Depth 5
    [IO.File]::WriteAllText((Join-Path $priv "tasks/manifest.json"), $bench, $utf8)
    $benchBefore = [IO.File]::ReadAllText((Join-Path $priv "tasks/manifest.json"))

    Write-Host "-- add"
    $r = Run @("-Step", "add", "-Id", "lfc-w01", "-Repo", $repo, "-Prompt", "make the digest shorter", "-PrivateRoot", $priv)
    Check "exit 0" $r.Exit 0
    $m = Get-Content -Raw (Join-Path $priv "tasks/real-work/manifest.json") | ConvertFrom-Json
    $t = @($m.tasks)[0]
    Check "the task is in the real-work manifest" $t.id "lfc-w01"
    Check "...based on the repository's HEAD" $t.benchBaseCommit $head
    Check "...graded checklist (no hidden tests)" $t.grading "checklist"
    Check "...its checklist the confirmed DONE.md" $t.checklist "lfc-w01/1/DONE.md"
    Check "...guard-rail scope" $t.scope "guardrails"
    Check "...the test command copied from the repo's benchmark task" ($t.testCmd -join " ") "npx vitest run"
    Check "...and its install flags" ($t.installFlags -join " ") "--ignore-scripts"
    Check "...the prompt in the owner's words" $t.prompt "make the digest shorter"
    Check "the benchmark manifest is untouched" ([IO.File]::ReadAllText((Join-Path $priv "tasks/manifest.json"))) $benchBefore
    $r = Run @("-Step", "add", "-Id", "lfc-w01", "-Repo", $repo, "-Prompt", "again", "-PrivateRoot", $priv)
    Check "a duplicate id is refused" $r.Exit 3
    $r = Run @("-Step", "add", "-Id", "lfc-w02", "-Repo", $repo, "-PrivateRoot", $priv)
    Check "no -Prompt: refused" $r.Exit 3
    $r = Run @("-Step", "add", "-Id", "lfc-w03", "-Repo", (Join-Path $tmp "nope"), "-Prompt", "x", "-PrivateRoot", $priv)
    Check "not a repository: refused" $r.Exit 3
    $other = Join-Path $tmp "Other"; & git init -q $other; & git -C $other config user.email g@x; & git -C $other config user.name g; [IO.File]::WriteAllText((Join-Path $other "b.txt"), "b`n", $utf8); & git -C $other add -A; & git -C $other commit -q -m b
    $r = Run @("-Step", "add", "-Id", "oth-w01", "-Repo", $other, "-Prompt", "x", "-PrivateRoot", $priv)
    Check "a repository with no benchmark task and no -TestCmd: refused" $r.Exit 3
    $r = Run @("-Step", "add", "-Id", "oth-w01", "-Repo", $other, "-Prompt", "x", "-TestCmd", "npm,test", "-PrivateRoot", $priv)
    Check "...accepted with -TestCmd" $r.Exit 0
    Check "...which is split on commas" ((@((Get-Content -Raw (Join-Path $priv "tasks/real-work/manifest.json") | ConvertFrom-Json).tasks | Where-Object id -eq "oth-w01")[0].testCmd) -join " ") "npm test"
    $r = Run @("-Step", "add", "-Id", "Bad_Id", "-Repo", $repo, "-Prompt", "x", "-PrivateRoot", $priv)
    Check "an id that is not lower-case-and-dashes: refused" ($r.Exit -ne 0) "True"

    Write-Host "-- run refuses an unconfirmed list"
    if ($python) {
        $dir = Join-Path $priv "tasks/real-work/lfc-w01/1"
        New-Item -ItemType Directory -Force $dir | Out-Null
        [IO.File]::WriteAllText((Join-Path $dir "DONE.md"), "# Done`n`n## Gate`n- [x] G1: shorter digest`n", $utf8)
        [IO.File]::WriteAllText((Join-Path $dir "digest.test.ts"), "it('G1: x', () => {})`n", $utf8)
        $r = Run @("-Step", "run", "-Id", "lfc-w01", "-PrivateRoot", $priv)
        Check "an unconfirmed DONE.md: exit 1" $r.Exit 1
        Check "...saying so" ($r.Out -match 'not confirmed') "True"
        Check "...before any run (no results folder)" (Test-Path (Join-Path $priv "results/real-work/lfc-w01")) "False"
        & $python.Source -I $doneTool confirm (Join-Path $dir "DONE.md") --by guard | Out-Null
        Remove-Item (Join-Path $dir "digest.test.ts")
        $r = Run @("-Step", "run", "-Id", "lfc-w01", "-PrivateRoot", $priv)
        Check "confirmed but no Gate tests: exit 1, before any run" "$($r.Exit) $(Test-Path (Join-Path $priv 'results/real-work/lfc-w01'))" "1 False"
    } else { Write-Host "SKIP the run refusals: no working python" }
    $r = Run @("-Step", "deliver", "-Id", "missing-01", "-PrivateRoot", $priv)
    Check "a task that was never added: exit 3" $r.Exit 3
} finally {
    Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue
}

Write-Host ""
if ($script:fail) { Write-Host "$script:fail FAILED"; exit 1 }
Write-Host "all passed"
exit 0
